function showReport(){if(getProduct(activeProduct)?.isDemo)return;if(!requireUser())return;const productId=activeProduct;form('รายงานปัญหา','<label>สาเหตุ<select name="reason"><option>ข้อมูลสินค้าไม่ตรงจริง</option><option>ขอให้โอนเงินนอกระบบ</option><option>แอบอ้างตัวตน</option><option>อื่น ๆ</option></select></label><label>รายละเอียด<textarea name="details" minlength="10" maxlength="1000" required></textarea></label>','ส่งรายงาน',async f=>{await write('/reports','POST',{...Object.fromEntries(f),productId});closeModal();toast('บันทึกรายงานแล้ว');});}
