document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;try{if(el.dataset.completeSample){el.disabled=true;try{await write('/orders/'+encodeURIComponent(el.dataset.completeSample)+'/complete-sample','POST',{});showOrders();toast('ยืนยันรับสินค้าจำลองเรียบร้อย');}finally{el.disabled=false;}return;}if(el.dataset.payOrder){showPayment(el.dataset.payOrder);return;}if(el.dataset.receiptOrder){showReceipt(el.dataset.receiptOrder);return;}if(el.dataset.fulfillOrder){el.disabled=true;try{await write('/orders/'+encodeURIComponent(el.dataset.fulfillOrder)+'/shops/'+encodeURIComponent(el.dataset.fulfillShop)+'/fulfill','POST',{status:el.dataset.fulfillStatus});await showSales();}finally{el.disabled=false;}return;}if(el.dataset.reviewReport){reviewReport(el.dataset.reviewReport);return;}if(el.dataset.pickupOrder){await showPickup(el.dataset.pickupOrder,el.dataset.pickupShop,el.dataset.pickupRole);return;}if(el.dataset.editProduct){editProduct(el.dataset.editProduct);return;}if(el.dataset.withdrawProduct){withdrawProduct(el.dataset.withdrawProduct);return;}if(el.dataset.mailUrl){e.preventDefault();location.hash=new URL(el.dataset.mailUrl,location.origin).hash;tokenForm();return;}if(el.dataset.product){e.preventDefault();showProduct(el.dataset.product);return;}if(el.dataset.favorite){if(getProduct(el.dataset.favorite)?.isDemo)return;if(!requireUser())return;await write('/favorites/'+encodeURIComponent(el.dataset.favorite),state.favorites.includes(el.dataset.favorite)?'DELETE':'PUT',{});return;}if(el.dataset.action&&actions[el.dataset.action]){await actions[el.dataset.action]();return;}if(el.dataset.cartAdd){await addCart(el.dataset.cartAdd);return;}if(el.dataset.removeCart){await write('/cart/'+encodeURIComponent(el.dataset.removeCart),'DELETE',{});showCart();return;}if(el.dataset.cancelOrder){await write('/orders/'+encodeURIComponent(el.dataset.cancelOrder)+'/cancel');showOrders();return;}if(el.dataset.reviewShop){await reviewShop(el.dataset.reviewShop);return;}if(el.dataset.category){category=el.dataset.category;limit=8;render();}if(el.dataset.filter){filter=el.dataset.filter;render();}if(el.dataset.view)navigate(el.dataset.view);if(el.dataset.store){storeFilter=el.dataset.store;view='discover';render();}}catch(err){toast(err.message);}});
