function auctionSignature(p){return JSON.stringify([p.roundId,p.status,p.price,p.bids,p.endsAt,p.lastAuctionResult,state.bids[p.id]]);}
async function refreshAuctionDetails(){const id=activeProduct,p=getProduct(id);if(!modal.open||p?.mode!=='auction'||(p.isDemo&&!p.bidableDemo)||!$('#modal-body .auction-summary')||auctionRefreshPending)return;const oldForm=$('#bid-form');if(oldForm?.querySelector('button')?.disabled)return;const input=oldForm?.querySelector('[name="amount"]'),value=input?.value,dirty=input&&input.value!==input.defaultValue,focused=document.activeElement===input,roundId=p.roundId,signature=auctionSignature(p),previousError=oldForm?.querySelector('.form-error')?.textContent;auctionRefreshPending=true;try{await refresh();if(activeProduct!==id||!modal.open||!$('#modal-body .auction-summary')||oldForm?.querySelector('button')?.disabled)return;const latest=getProduct(id);if(!latest||auctionSignature(latest)===signature)return;showProduct(id);const next=$('#bid-form [name="amount"]');if(dirty&&next)next.value=value;if(next){const error=$('#bid-form .form-error');if(roundId!==latest.roundId)error.textContent='เริ่มรอบใหม่แล้ว จำนวนที่คุณกรอกยังอยู่ เสนอครั้งถัดไปอย่างน้อย '+money(latest.price+latest.step);else if(dirty&&Number(value)<latest.price+latest.step)error.textContent='มีราคาใหม่แล้ว เสนอครั้งถัดไปอย่างน้อย '+money(latest.price+latest.step);else if(previousError)error.textContent=previousError;}if(focused&&next)next.focus();}catch{}finally{auctionRefreshPending=false;}}
